#!/usr/bin/env bash
# Question 1: VPA for processor not working. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl get apiservice v1beta1.metrics.k8s.io >/dev/null 2>&1 || {
  echo "this cluster image has no metrics-server: rebuild images with ./cka images build --force" >&2
  exit 1
}
kubectl get crd verticalpodautoscalers.autoscaling.k8s.io >/dev/null 2>&1 || {
  echo "this cluster image has no Vertical Pod Autoscaler: rebuild images with ./cka images build --force" >&2
  exit 1
}
kubectl create namespace "finops" >/dev/null 2>&1 || kubectl get namespace "finops" >/dev/null
timeout 60 bash -c "until kubectl -n 'finops' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: processor
  namespace: finops
  labels: { app: processor }
spec:
  replicas: 0
  selector:
    matchLabels: { app: processor }
  template:
    metadata:
      labels: { app: processor }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
          resources:
            requests: { cpu: 50m, memory: 32Mi }
---
apiVersion: autoscaling.k8s.io/v1
kind: VerticalPodAutoscaler
metadata:
  name: processor-vpa
  namespace: finops
spec:
  targetRef: { apiVersion: apps/v1, kind: Deployment, name: processor }
  updatePolicy: { updateMode: Recreate }
EOF
kubectl -n "finops" get deployment "processor" -o jsonpath='{.metadata.uid}' > "/var/tmp/cka-q1.uid"
chmod 644 "/var/tmp/cka-q1.uid"

case "${Q1_FAULT}" in
  recommender-rbac)
    kubectl get clusterrolebinding vpa-status-actor -o json > "/var/tmp/cka-q1.crb.json"
    kubectl delete clusterrolebinding vpa-status-actor
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

kubectl -n "finops" scale "deployment/processor" --replicas=2
kubectl -n "finops" rollout status "deployment/processor" --timeout=120s >/dev/null 2>&1 || true
